import sys, math
import torch
_P = False
def run(hidden_states, residual, weight, eps=1e-6):
    global _P
    if not _P:
        _P = True
        sys.stderr.write("[TRACE_APPLY_SOLUTION] fused_add_rmsnorm (value-returning) invoked\n"); sys.stderr.flush()
    s = hidden_states.to(torch.float32) + residual.to(torch.float32)   # new residual (pre-norm sum)
    var = s.pow(2).mean(dim=-1, keepdim=True)
    out = (s * torch.rsqrt(var + eps)) * weight.to(torch.float32)       # normalized output
    return out.to(hidden_states.dtype), s.to(residual.dtype)            # (output, residual)
